CREATE TYPE "ChronicleSessionWorkStatus" AS ENUM ('PENDING', 'COMPLETED');
ALTER TABLE "chronicles" ADD COLUMN "currentSituation" TEXT;
ALTER TABLE "chronicle_participants" ADD COLUMN "narratorNotes" TEXT, ADD COLUMN "revision" INTEGER NOT NULL DEFAULT 1;
ALTER TABLE "chronicle_sessions" ADD COLUMN "objective" TEXT, ADD COLUMN "plannedSummary" TEXT, ADD COLUMN "revision" INTEGER NOT NULL DEFAULT 1;
CREATE TABLE "chronicle_session_scenes" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "chronicleId" UUID NOT NULL, "sessionId" UUID NOT NULL, "title" TEXT NOT NULL, "purpose" TEXT, "narrativePhase" TEXT, "intensity" INTEGER, "sortOrder" INTEGER NOT NULL, "status" "ChronicleSessionWorkStatus" NOT NULL DEFAULT 'PENDING', "revision" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "chronicle_session_scenes_pkey" PRIMARY KEY ("id"), CONSTRAINT "chronicle_session_scenes_title_check" CHECK (char_length(btrim("title")) BETWEEN 1 AND 160), CONSTRAINT "chronicle_session_scenes_intensity_check" CHECK ("intensity" IS NULL OR "intensity" BETWEEN 1 AND 5), CONSTRAINT "chronicle_session_scenes_sort_check" CHECK ("sortOrder" >= 0));
CREATE TABLE "chronicle_session_preparation_items" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "chronicleId" UUID NOT NULL, "sessionId" UUID NOT NULL, "text" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL, "status" "ChronicleSessionWorkStatus" NOT NULL DEFAULT 'PENDING', "revision" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "chronicle_session_preparation_items_pkey" PRIMARY KEY ("id"), CONSTRAINT "chronicle_session_preparation_text_check" CHECK (char_length(btrim("text")) BETWEEN 1 AND 500), CONSTRAINT "chronicle_session_preparation_sort_check" CHECK ("sortOrder" >= 0));
CREATE TABLE "chronicle_event_character_links" ("eventId" UUID NOT NULL, "characterId" UUID NOT NULL, "chronicleId" UUID NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "chronicle_event_character_links_pkey" PRIMARY KEY ("eventId", "characterId"));
CREATE TABLE "chronicle_event_npc_links" ("eventId" UUID NOT NULL, "npcId" UUID NOT NULL, "chronicleId" UUID NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "chronicle_event_npc_links_pkey" PRIMARY KEY ("eventId", "npcId"));
CREATE TABLE "chronicle_event_location_links" ("eventId" UUID NOT NULL, "locationId" UUID NOT NULL, "chronicleId" UUID NOT NULL, "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "chronicle_event_location_links_pkey" PRIMARY KEY ("eventId", "locationId"));
CREATE UNIQUE INDEX "chronicle_session_scenes_sessionId_sortOrder_key" ON "chronicle_session_scenes"("sessionId", "sortOrder"); CREATE INDEX "chronicle_session_scenes_chronicleId_sessionId_idx" ON "chronicle_session_scenes"("chronicleId", "sessionId"); CREATE UNIQUE INDEX "chronicle_session_preparation_sessionId_sortOrder_key" ON "chronicle_session_preparation_items"("sessionId", "sortOrder"); CREATE INDEX "chronicle_session_preparation_chronicleId_sessionId_idx" ON "chronicle_session_preparation_items"("chronicleId", "sessionId"); CREATE INDEX "chronicle_event_character_links_characterId_idx" ON "chronicle_event_character_links"("characterId"); CREATE INDEX "chronicle_event_npc_links_npcId_idx" ON "chronicle_event_npc_links"("npcId"); CREATE INDEX "chronicle_event_location_links_locationId_idx" ON "chronicle_event_location_links"("locationId");
ALTER TABLE "chronicle_session_scenes" ADD CONSTRAINT "chronicle_session_scenes_session_fkey" FOREIGN KEY ("sessionId", "chronicleId") REFERENCES "chronicle_sessions"("id", "chronicleId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "chronicle_session_scenes" ADD CONSTRAINT "chronicle_session_scenes_chronicle_fkey" FOREIGN KEY ("chronicleId") REFERENCES "chronicles"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "chronicle_session_preparation_items" ADD CONSTRAINT "chronicle_session_preparation_session_fkey" FOREIGN KEY ("sessionId", "chronicleId") REFERENCES "chronicle_sessions"("id", "chronicleId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "chronicle_session_preparation_items" ADD CONSTRAINT "chronicle_session_preparation_chronicle_fkey" FOREIGN KEY ("chronicleId") REFERENCES "chronicles"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "chronicle_event_character_links" ADD CONSTRAINT "chronicle_event_character_event_fkey" FOREIGN KEY ("eventId", "chronicleId") REFERENCES "chronicle_events"("id", "chronicleId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "chronicle_event_character_links" ADD CONSTRAINT "chronicle_event_character_character_fkey" FOREIGN KEY ("characterId", "chronicleId") REFERENCES "characters"("id", "chronicleId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "chronicle_event_npc_links" ADD CONSTRAINT "chronicle_event_npc_event_fkey" FOREIGN KEY ("eventId", "chronicleId") REFERENCES "chronicle_events"("id", "chronicleId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "chronicle_event_npc_links" ADD CONSTRAINT "chronicle_event_npc_npc_fkey" FOREIGN KEY ("npcId", "chronicleId") REFERENCES "chronicle_npcs"("id", "chronicleId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "chronicle_event_location_links" ADD CONSTRAINT "chronicle_event_location_event_fkey" FOREIGN KEY ("eventId", "chronicleId") REFERENCES "chronicle_events"("id", "chronicleId") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "chronicle_event_location_links" ADD CONSTRAINT "chronicle_event_location_location_fkey" FOREIGN KEY ("locationId", "chronicleId") REFERENCES "chronicle_locations"("id", "chronicleId") ON DELETE RESTRICT ON UPDATE CASCADE;
